//! Actions-only actual bootstrap/SDK/UserEntry/P2P span -> original manual
//! setRead WRITE. No user UDMR grant, original library/device or paid traffic.
#[path="im_send_recipient_account_tests.rs"]
mod im_sends;
use super::*;
use super::super::super::super as n;
async fn bounded<F:std::future::Future>(f:F)->F::Output{tokio::time::timeout(Duration::from_secs(12),f).await.expect("original owned account fixture deadline")}
fn config(root:&str,port:u16)->n::account_config::AccountConfig{let c=bootstrap_account_config(root,port);let mut v:serde_json::Value=serde_json::from_slice(&c.encode_private().unwrap()).unwrap();v["config"]["profile"]["incoming"]=serde_json::Value::Null;v["config"]["profile"]["native_receivers"]=serde_json::json!({"im_messages":{"notification_timeout_ms":3000}});v["config"]["profile"]["client_ex"]=serde_json::json!(true);v["config"]["profile"]["im_sync"]=serde_json::json!({"receive":true});v["config"]["profile"]["im_read_status"]=serde_json::json!({"set_read_status":true});v["config"]["profile"]["im_user_read"]=serde_json::Value::Null;v["config"]["profile"]["im_receipts"]=serde_json::Value::Null;n::account_config::AccountConfig::decode_private(&serde_json::to_vec(&v).unwrap()).unwrap()}
async fn poll(peer:&mut CommonPeer,p:&n::rpc_envelope::RpcRequest<'_>){assert_eq!(p.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut a=Reader::versioned(p.arguments).unwrap();a.bytes().unwrap();a.bytes().unwrap();let data=n::rpc_batch::read_payload(&mut a).unwrap();assert!(data.results.is_empty());let seq=data.requests.keys().copied().max();peer.send(&[reply(p.call_id,&super::super::tests::swap_result(seq,true,data.fields))]).await;}
async fn next(peer:&mut CommonPeer,method:&str)->Vec<u8>{loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0);let r=decode_request(&p[1..]).unwrap();if r.method==method.as_bytes(){return p;}poll(peer,&r).await;}}
fn status()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();w.properties(&[RpcProperty{key:n::im_status::PEER_READ,value:b"0"},RpcProperty{key:n::im_status::LATEST,value:b"3"}]).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn records()->Vec<u8>{records_span(1,3)}
fn records_span(start:i64,count:u32)->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(count).unwrap();for id in start..start+i64::from(count){w.i64(id).unwrap();w.i64(1).unwrap();w.bytes(b"fixture-sender").unwrap();w.bytes(b"Text").unwrap();w.bytes(br#"{"text":"original manual recipient span"}"#).unwrap();w.properties(&[]).unwrap();w.properties(&[]).unwrap();}w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn aid(mode:u8)->Vec<u8>{let mut w=Writer::new();w.boolean(mode!=2).unwrap();w.u32(1).unwrap();w.bytes(if mode==1{b"9_9"}else{b"1_2"}).unwrap();w.bytes(b"phone").unwrap();w.bytes(b"+12345").unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn retired(peer:&mut CommonPeer){for _ in 0..128{let Some(p)=peer.next_input_only().await else{return;};if matches!(p.as_slice(),[2]|[14]){continue;}assert_eq!(p[0],0);let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes(),"no setRead/unhosting/logout/user mark/replay after original retirement");let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.bytes().unwrap(),b"fixture-original-selector");let p=n::rpc_batch::read_payload(&mut a).unwrap();assert!(p.requests.is_empty()&&p.results.is_empty());a.finish().unwrap();}panic!("retired original input exceeded existing128 cap")}
fn online_four()->Vec<u8>{let mut w=Writer::new();w.i64(4).unwrap();w.i64(1).unwrap();w.bytes(b"fixture-sender").unwrap();w.bytes(b"Text").unwrap();w.bytes(br#"{"text":"current span advanced during recipient lookup"}"#).unwrap();w.properties(&[]).unwrap();w.properties(&[]).unwrap();let mut a=Writer::versioned().unwrap();a.bytes(n::im_data::MORE_MESSAGE_KIND).unwrap();a.properties(&[RpcProperty{key:b"Box",value:b"P2P/1_2"}]).unwrap();a.bytes(w.finish().expose_to_transport()).unwrap();let e=encode_request(91,&[RpcProperty{key:b"id",value:b"MessageReceiver"},RpcProperty{key:b"__magic",value:&[9,1]}],n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),a.finish().expose_to_transport()).unwrap();let mut p=vec![0];p.extend_from_slice(e.expose_to_transport());p}
async fn scenario(mode:u8){
    let cert=Certificates::generate("IP:127.0.0.1");let front=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=front.local_addr().unwrap().port();let boot=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let main=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let aux=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let ports=[boot.local_addr().unwrap().port(),main.local_addr().unwrap().port(),aux.local_addr().unwrap().port()];let server=cert.server_config(&TLS13);let source_server=server.clone();let main_server=server.clone();let(observed,submitted)=oneshot::channel();let(release,reply_ready)=oneshot::channel();let(done,finish)=oneshot::channel();let(aux_observed,aux_seen)=oneshot::channel();let(aux_release,aux_ready)=oneshot::channel();let(advance,advancing)=oneshot::channel();let temp=n::account_test_support::TempDatabase::new();let manager=n::account_runtime::AccountManager::new(temp.database.clone());let created=manager.create(config(&cert.root,port),100).await.unwrap();let line=created.account.line_id.clone();let db=temp.database.clone();
    let relay=tokio::spawn(async move{bounded(async move{let mut joins=Vec::new();for target in ports{let(mut a,_)=front.accept().await.unwrap();let mut b=tokio::net::TcpStream::connect((std::net::Ipv4Addr::LOCALHOST,target)).await.unwrap();joins.push(tokio::spawn(async move{let _=tokio::io::copy_bidirectional(&mut a,&mut b).await;}));}for j in joins{j.await.unwrap();}}).await});
    let source=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(boot,source_server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_bootstrap::GET_APP_CONFIGS_METHOD.as_bytes());peer.send(&[reply(r.call_id,&bootstrap_user_entry())]).await;peer.no_more_common().await;}).await});
    let sdk=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(main,main_server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_login::LOGIN_SESSION_METHOD.as_bytes());peer.send(&[reply(r.call_id,&login_result_for_account())]).await;let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"4");let p=next(&mut peer,n::im_status::REFRESH_METHOD).await;let r=decode_request(&p[1..]).unwrap();peer.send(&[reply(r.call_id,&status())]).await;let p=next(&mut peer,n::im_data::RECV_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"P2P/1_2");assert_eq!(a.i64().unwrap(),1);assert_eq!(a.u32().unwrap(),3);a.finish().unwrap();peer.send(&[reply(r.call_id,&records())]).await;
        if mode==7{advancing.await.unwrap();peer.send(&[online_four()]).await;loop{let p=peer.next().await.unwrap();if p[0]==1{assert_eq!(decode_reply(&p[1..]).unwrap().call_id,91);break;}let r=decode_request(&p[1..]).unwrap();poll(&mut peer,&r).await;}}
        if mode!=1&&mode!=2&&mode!=7{let p=next(&mut peer,n::im_data::SET_READ_METHOD).await;let r=decode_request(&p[1..]).unwrap();assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"P2P/1_2");assert_eq!(a.i64().unwrap(),3);a.finish().unwrap();let state:(i64,Option<i32>,Option<Vec<u8>>)=db.with_conn(|c|c.query_row("SELECT state,request_id,recipient_hash FROM app_voice_im_read_status_actions",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"fixture")).unwrap();assert_eq!(state.0,0);assert_eq!(state.1,Some(r.call_id));assert_eq!(state.2.unwrap().len(),32);observed.send(()).unwrap();if mode==4{reply_ready.await.unwrap();retired(&mut peer).await;return;}if mode==5{reply_ready.await.unwrap();peer.send(&[reply(r.call_id,&[0,1,0,0,0,0])]).await;retired(&mut peer).await;return;}peer.send(&[reply(r.call_id,if mode==3{&[0;6]}else{&[0,1,0,0,0,0]})]).await;}
        finish.await.unwrap();let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"3");logout_peer(peer).await;
    }).await});
    let resolver=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(aux,server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::user_entry_data::AID_TO_UID_METHOD.as_bytes());assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"prefix/UserEntry");assert_eq!(r.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");if mode==6||mode==7{aux_observed.send(()).unwrap();aux_ready.await.unwrap();}peer.send(&[reply(r.call_id,&aid(mode))]).await;peer.no_more_common().await;}).await});
    manager.start(&line,1,100).await.unwrap();let target=bounded(async{loop{if let Some(v)=manager.im_read_status_targets(&line,1).await.ok().and_then(|mut v|v.pop()){break v;}tokio::task::yield_now().await;}}).await;let uri="[phone:+12345@account-domain.invalid]";let nonce="a".repeat(32);assert_eq!(manager.set_im_read_status_via_recipient(&line,2,target.id,"3",&nonce,uri,true).await.err(),Some("app_account_revision_conflict"));assert_eq!(manager.set_im_read_status_via_recipient(&line,1,target.id,"3",&nonce,uri,false).await.err(),Some("app_account_im_read_status_consent_required"));let view=manager.get(&line,100).await.unwrap();assert_eq!(view.im_read_status_recipient_supported,Some(true));assert_eq!(view.im_user_read_supported,Some(false));let mut operation=Box::pin(manager.set_im_read_status_via_recipient(&line,1,target.id,"3",&nonce,uri,true));
    if mode==6||mode==7{tokio::select!{v=operation.as_mut()=>panic!("resolver has not returned: {v:?}"),_=bounded(aux_seen)=>{}}if mode==6{assert_eq!(manager.set_im_read_status(&line,1,target.id,"3",&nonce,true).await.err(),Some("app_account_im_read_status_nonce_conflict"));assert_eq!(manager.set_im_read_status_via_recipient(&line,1,target.id,"3",&nonce,uri,true).await.err(),Some("app_account_im_read_status_resolution_inflight"));assert_eq!(manager.set_im_read_status_via_recipient(&line,1,target.id,"3",&nonce,"[phone:+67890@account-domain.invalid]",true).await.err(),Some("app_account_im_read_status_nonce_conflict"));assert!(manager.im_read_status_history(&line,16).unwrap().is_empty());drop(advance);}else{advance.send(()).unwrap();bounded(async{loop{if manager.im_read_status_targets(&line,1).await.unwrap().iter().any(|t|t.target_index=="4"){break;}tokio::task::yield_now().await;}}).await;}aux_release.send(()).unwrap();}else{drop(aux_release);drop(advance);}
    if mode==4||mode==5{tokio::select!{value=operation.as_mut()=>panic!("original WRITE still has no result: {value:?}"),_=bounded(submitted)=>{}}if mode==4{drop(operation);release.send(()).unwrap();}else{temp.database.with_conn(|c|c.execute("UPDATE app_voice_im_read_status_actions SET recipient_hash=NULL",[]).map_err(|_|"fixture")).unwrap();release.send(()).unwrap();assert_eq!(bounded(operation).await.err(),Some("app_account_im_read_status_uncertain"));}bounded(async{while manager.get(&line,100).await.unwrap().phase!="disconnected"{tokio::task::yield_now().await;}}).await;assert_eq!(manager.im_read_status_history(&line,16).unwrap()[0].state,"uncertain");assert!(manager.set_im_read_status_via_recipient(&line,1,target.id,"3",&"b".repeat(32),uri,true).await.is_err());drop(done);}else{let result=bounded(operation).await;if mode==1||mode==2||mode==7{assert_eq!(result.err(),Some(if mode==7{"app_account_im_read_status_recipient_target_stale"}else{"app_account_im_read_status_recipient_unconfirmed"}));assert!(manager.im_read_status_history(&line,16).unwrap().is_empty());if mode==7{let count:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_read_receipts",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(count,0);assert_eq!(manager.get(&line,100).await.unwrap().phase,"hosted");}}else{let v=result.unwrap();assert_eq!(v.state,if mode==3{"rejected"}else{"confirmed"});let same=manager.set_im_read_status_via_recipient(&line,1,target.id,"3",&nonce,uri,true).await.unwrap();assert_eq!(same.id,v.id);assert_eq!(same.state,v.state);assert_eq!(manager.set_im_read_status_via_recipient(&line,1,target.id,"3",&nonce,"[phone:+67890@account-domain.invalid]",true).await.err(),Some("app_account_im_read_status_nonce_conflict"));}done.send(()).unwrap();drop(release);}
    assert!(manager.im_user_read_history(&line,16).unwrap().is_empty());assert!(manager.messages(&line,16).unwrap().is_empty());assert_eq!(manager.im_messages(&line,16).unwrap().len(),if mode==7{4}else{3});let stopped=manager.stop(&line,1,100).await.unwrap();assert!(!stopped.io_cleanup_required);assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());assert_eq!(manager.shutdown_all().await,0);bounded(async{source.await.unwrap();sdk.await.unwrap();resolver.await.unwrap();relay.await.unwrap();}).await;
}
#[tokio::test]async fn manual_recipient_actual_uid_match_sets_original_p2p_position_without_user_udmr_and_all_joins(){Box::pin(scenario(0)).await;}
#[tokio::test]async fn manual_recipient_actual_wrong_uid_cannot_set_a_different_current_span_position(){Box::pin(scenario(1)).await;}
#[tokio::test]async fn manual_recipient_actual_negative_lookup_is_not_a_manual_write_permission(){Box::pin(scenario(2)).await;}
#[tokio::test]async fn manual_recipient_actual_known_rejected_same_nonce_never_replays_lookup_or_write(){Box::pin(scenario(3)).await;}
#[tokio::test]async fn manual_recipient_actual_full_write_cancel_keeps_original_unknown_and_actual_joins(){Box::pin(scenario(4)).await;}
#[tokio::test]async fn manual_recipient_actual_changed_hash_before_private_reply_keeps_both_unknown_and_joins(){Box::pin(scenario(5)).await;}
#[tokio::test]async fn manual_recipient_actual_pending_lookup_same_nonce_and_changed_metadata_admit_one_aux_query(){Box::pin(scenario(6)).await;}
#[tokio::test]async fn manual_recipient_actual_cursor_advance_during_lookup_is_known_no_write_and_sdk_healthy(){Box::pin(scenario(7)).await;}
